## 5. Full minimal project snippet

```kotlin
// ---- TileVault.kt ---------------------------------------------------------
class TileVault(private val ctx: Context) {

    // Example: encrypted tiles are stored under /data/user/0/<pkg>/files/vault/{z}/{x}/{y}.enc
    fun readEncryptedTile(z: Int, x: Int, y: Int): ByteArray {
        val file = File(ctx.filesDir, "vault/$z/$x/$y.enc")
        return file.readBytes()
    }

    // Replace with your real crypto – this is just a placeholder.
    fun decrypt(encrypted: ByteArray): ByteArray {
        // e.g. AES-GCM with a key stored in Android Keystore
        return MyCrypto.decrypt(encrypted)
    }
}

// ---- VaultRequestHandler.kt ------------------------------------------------
class VaultRequestHandler(
    private val vault: TileVault
) : HttpRequestHandler {

    override fun handleRequest(request: HttpRequest): HttpResponse {
        val url = request.url
        if (url.scheme == "vault") {
            val seg = url.pathSegments
            if (seg.size >= 4 && seg[0] == "tiles") {
                val z = seg[1].toInt()
                val x = seg[2].toInt()
                val y = seg[3].toInt()

                val plain = vault.decrypt(vault.readEncryptedTile(z, x, y))
                return HttpResponse(
                    code = 200,
                    body = plain.inputStream(),
                    headers = mapOf("Content-Type" to "application/x-protobuf")
                )
            }
            return HttpResponse(400, null, emptyMap())
        }
        return HttpResponse(404, null, emptyMap())
    }
}

// ---- MyApplication.kt ------------------------------------------------------
class MyApplication : Application() {
    override fun onCreate() {
        super.onCreate()
        val vault = TileVault(this)

        val options = MapLibreOptions()
        options.httpRequestHandler = VaultRequestHandler(vault)

        MapLibre.getInstance(this, options)
    }
}

// ---- MainActivity.kt -------------------------------------------------------
class MainActivity : AppCompatActivity() {

    private lateinit var mapView: MapView

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)

        // layout contains <com.mapbox.mapboxsdk.maps.MapView android:id="@+id/mapView" …/>
        setContentView(R.layout.activity_main)
        mapView = findViewById(R.id.mapView)
        mapView.onCreate(savedInstanceState)

        mapView.getMapAsync { mapboxMap ->
            mapboxMap.setStyle(
                Style.Builder()
                    .fromUri("asset://my_style.json")   // style contains vault://tiles/…
            )
        }
    }

    // … forward lifecycle calls to mapView (onStart, onStop, …) …
}
```

That’s it – the SDK now treats `vault://…` exactly like a normal HTTP URL, but you supply the decrypted bytes yourself.

